import rspack, { Configuration } from '@rspack/core';
import { html } from './html';
import { AssetManifest } from './getAssetManifest';

export type GenerateTemplateOptions = {
  title: string;
  publicDir: string;
  publicPath: string;
};

export function generateHtmlTemplate(options: GenerateTemplateOptions) {
  const assetManifest = AssetManifest.fromPath(options.publicDir);
  const scriptTags = assetManifest.getTags(options.publicPath);
  const template = html(options.title || 'Bit Preview');
  const templateWithScripts = template.replace('<!--scripts-->', scriptTags);

  return templateWithScripts;
}

export function getHtmlPlugin(options: any = {}): Partial<Configuration> {
  return new rspack.HtmlRspackPlugin({
    // templateContent: html(options.title || 'Bit Preview'),
    templateContent: generateHtmlTemplate({
      title: options.title,
      publicDir: options.publicDirectory,
      publicPath: '',
      // indexHtmlPath: join(componentDir, 'index.html'),
    }),
    filename: 'index.html',
    ...options,
  });
}
